from agent_envs.result_parser import parse_result
from agent_envs.proxy_client import ExecResult
from agent_envs.problems import CppOJ
from agent_envs.solutions import OJResultStatus

async def test_cpp_oj_result_parsing():
    exec_result = {'stdout': '', 'stderr': '', 'exit_code': 0, 'files': [{'filename': 'workspace/judge_result.jsonl', 'content': ''}]}
    er = ExecResult.from_json(exec_result)
    r = await parse_result(CppOJ(files=[], test_cases=[]), er)
    assert r.status == OJResultStatus.SE